def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        a = list(map(int, data[index:index + n]))
        index += n

        tag_count = defaultdict(int)
        for tag in a:
            tag_count[tag] += 1

        if any(count > 1 for count in tag_count.values()):
            results.append(-1)
            continue

        # Create a list of indices for each tag
        tag_indices = defaultdict(list)
        for i, tag in enumerate(a):
            tag_indices[tag].append(i)

        # Sort indices to try to minimize jumps
        for indices in tag_indices.values():
            indices.sort()

        # Try to construct a valid permutation
        permutation = [-1] * n
        used = [False] * n
        cost = 0

        def backtrack(pos):
            nonlocal cost
            if pos == n:
                return True

            for tag in tag_indices:
                for idx in tag_indices[tag]:
                    if not used[idx]:
                        if pos == 0 or a[permutation[pos - 1]] != tag:
                            used[idx] = True
                            permutation[pos] = idx
                            if pos > 0:
                                cost += abs(idx - permutation[pos - 1]) > 1
                            if backtrack(pos + 1):
                                return True
                            cost -= abs(idx - permutation[pos - 1]) > 1
                            used[idx] = False
            return False

        if backtrack(0):
            results.append(cost)
        else:
            results.append(-1)

    for result in results:
        print(result)

